package com.hospital.system.controller; import com.hospital.system.model.Department; import com.hospital.system.service.DepartmentService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/departments") public class DepartmentController {private final DepartmentService s; public DepartmentController(DepartmentService s){this.s=s;} @GetMapping public Object all(){return s.all();} @GetMapping("/{id}") public Department one(@PathVariable Long id){return s.one(id);} @PostMapping public ResponseEntity<Department> add(@RequestBody Department x){return ResponseEntity.status(201).body(s.add(x));} @PutMapping("/{id}") public Department update(@PathVariable Long id,@RequestBody Department x){return s.update(id,x);} @DeleteMapping("/{id}") public ResponseEntity<Void> del(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();} }
